    @location(0) v_data0: vec2f,
    @location(1) v_data1: vec3f,
    @location(2) v_fill_color: vec4f,
    @location(3) v_halo_color: vec4f,
    @location(4) v_opacity: f32,
    @location(5) v_halo_width: f32,
