    var dist: f32 = textureSample(u_texture, u_textureSampler, tex).r;
    var gamma_scaled: f32 = gamma * gamma_scale;
    var alpha: f32 = smoothstep(inner_edge - gamma_scaled, inner_edge + gamma_scaled, dist);
